insert into venues (slug, name, description_de, address_street, address_zip, address_city, location, website_url, capacity, is_verified) values
  ('hubertussaal', 'Hubertussaal', 'Historischer Konzertsaal im Nordtrakt von Schloss Nymphenburg, größter der drei Säle im Orangerietrakt mit Platz für rund 400 Gäste.', 'Schloss Nymphenburg 1', '80638', 'München', ST_MakePoint(11.5032967, 48.1582569)::geography, 'https://www.schlosskonzerte-nymphenburg.de/', 400, false),
  ('max-joseph-saal', 'Max-Joseph-Saal', 'Klassizistischer Festsaal in der Münchner Residenz mit Stuckdekor und Kristalllüstern, einer der akustisch besten Kammermusiksäle der Stadt.', 'Residenzstraße 1', '80333', 'München', ST_MakePoint(11.5778676, 48.1421714)::geography, 'https://www.schloesser.bayern.de/deutsch/raeume/objekte/mu_r_mj.htm', 330, false),
  ('alte-kongresshalle', 'Alte Kongresshalle', 'Denkmalgeschützte, retrofuturistische Veranstaltungshalle von 1952/53 auf der Theresienhöhe, seit 2007 als Eventlocation genutzt.', 'Theresienhöhe 14', '80339', 'München', ST_MakePoint(11.5458135, 48.1327267)::geography, 'https://www.altekongresshalle.de/', 850, false),
