  ('carl-orff-auditorium', 'Carl-Orff-Auditorium', 'Kleiner Konzertsaal der Hochschule für Musik und Theater in der Dependance Luisenstraße, ehemalige Reaktorhalle. Nicht zu verwechseln mit dem gleichnamigen Saal im alten Gasteig-Gebäude.', 'Luisenstraße 37a', '80333', 'München', ST_MakePoint(11.5647517, 48.1482436)::geography, 'https://www.hmtm.de/', 116, false),
  ('rubinstein-saal', 'Rubinstein-Saal', 'Konzertsaal des Tonkünstlerverbands München mit Steinway-Flügel, genutzt für Schüler- und Kammerkonzerte.', 'Landsberger Straße 336', '80687', 'München', ST_MakePoint(11.4956052, 48.1441221)::geography, 'https://www.tonkuenstler-muenchen.de/', null, false),
